CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '', avatar_url text, preferences jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profiles_read ON public.profiles FOR SELECT TO authenticated USING (id=auth.uid());
CREATE POLICY profiles_insert ON public.profiles FOR INSERT TO authenticated WITH CHECK (id=auth.uid());
CREATE POLICY profiles_update ON public.profiles FOR UPDATE TO authenticated USING (id=auth.uid()) WITH CHECK (id=auth.uid());
CREATE FUNCTION public.create_user_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN INSERT INTO public.profiles(id,display_name) VALUES (new.id,coalesce(new.raw_user_meta_data->>'display_name','')); RETURN new; END; $$;
REVOKE ALL ON FUNCTION public.create_user_profile() FROM PUBLIC;
CREATE TRIGGER weorex_user_profile AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_user_profile();
CREATE TABLE public.organizations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL CHECK (length(name) BETWEEN 2 AND 120), slug text NOT NULL UNIQUE CHECK (slug ~ '^[a-z0-9][a-z0-9-]{1,79}$'), owner_user_id uuid NOT NULL, default_currency text NOT NULL DEFAULT 'USD' CHECK (default_currency ~ '^[A-Z]{3}$'), default_country text CHECK (default_country ~ '^[A-Z]{2}$'), timezone text NOT NULL DEFAULT 'UTC', status text NOT NULL DEFAULT 'active' CHECK (status IN ('active','suspended','archived')), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT ON public.organizations TO authenticated;
GRANT UPDATE(name,default_currency,default_country,timezone) ON public.organizations TO authenticated;
GRANT ALL ON public.organizations TO service_role;
ALTER TABLE public.organizations ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.organization_roles (organization_id uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE, role_key text NOT NULL CHECK (role_key IN ('owner','admin','member')), display_name text NOT NULL, PRIMARY KEY (organization_id,role_key));
GRANT SELECT ON public.organization_roles TO authenticated;
GRANT ALL ON public.organization_roles TO service_role;
ALTER TABLE public.organization_roles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.organization_memberships (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE, user_id uuid NOT NULL, role_key text NOT NULL DEFAULT 'member', status text NOT NULL DEFAULT 'active' CHECK (status IN ('invited','active','suspended')), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,user_id), FOREIGN KEY(organization_id,role_key) REFERENCES public.organization_roles(organization_id,role_key));
GRANT SELECT ON public.organization_memberships TO authenticated;
GRANT ALL ON public.organization_memberships TO service_role;
ALTER TABLE public.organization_memberships ENABLE ROW LEVEL SECURITY;
CREATE INDEX memberships_user_active ON public.organization_memberships(user_id,status);
CREATE FUNCTION public.is_org_member(p_org_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$ SELECT EXISTS (SELECT 1 FROM public.organization_memberships m JOIN public.organizations o ON o.id=m.organization_id WHERE m.organization_id=p_org_id AND m.user_id=auth.uid() AND m.status='active' AND o.status='active') $$;
CREATE FUNCTION public.has_org_role(p_org_id uuid,p_roles text[]) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$ SELECT public.is_org_member(p_org_id) AND EXISTS(SELECT 1 FROM public.organization_memberships WHERE organization_id=p_org_id AND user_id=auth.uid() AND status='active' AND role_key=ANY(p_roles)) $$;
REVOKE ALL ON FUNCTION public.is_org_member(uuid), public.has_org_role(uuid,text[]) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.is_org_member(uuid), public.has_org_role(uuid,text[]) TO authenticated;
CREATE POLICY organizations_read ON public.organizations FOR SELECT TO authenticated USING (public.is_org_member(id));
CREATE POLICY organizations_create ON public.organizations FOR INSERT TO authenticated WITH CHECK (owner_user_id=auth.uid() AND status='active');
CREATE POLICY organizations_edit ON public.organizations FOR UPDATE TO authenticated USING (public.has_org_role(id,ARRAY['owner','admin'])) WITH CHECK (public.has_org_role(id,ARRAY['owner','admin']));
CREATE POLICY memberships_read ON public.organization_memberships FOR SELECT TO authenticated USING (public.is_org_member(organization_id));
CREATE POLICY roles_read ON public.organization_roles FOR SELECT TO authenticated USING (public.is_org_member(organization_id));
CREATE FUNCTION public.bootstrap_organization() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN INSERT INTO public.organization_roles VALUES(new.id,'owner','Owner'),(new.id,'admin','Administrator'),(new.id,'member','Member'); INSERT INTO public.organization_memberships(organization_id,user_id,role_key) VALUES(new.id,new.owner_user_id,'owner'); RETURN new; END; $$;
REVOKE ALL ON FUNCTION public.bootstrap_organization() FROM PUBLIC;
CREATE TRIGGER weorex_organization_bootstrap AFTER INSERT ON public.organizations FOR EACH ROW EXECUTE FUNCTION public.bootstrap_organization();
CREATE TABLE public.audit_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE, actor_user_id uuid, action text NOT NULL, resource_type text NOT NULL, resource_id uuid, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.audit_logs TO authenticated;
GRANT ALL ON public.audit_logs TO service_role;
ALTER TABLE public.audit_logs ENABLE ROW LEVEL SECURITY;
CREATE POLICY audit_read ON public.audit_logs FOR SELECT TO authenticated USING(public.has_org_role(organization_id,ARRAY['owner','admin']));
CREATE FUNCTION public.audit_organization_changes() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN INSERT INTO public.audit_logs(organization_id,actor_user_id,action,resource_type,resource_id) VALUES(new.id,auth.uid(),CASE WHEN TG_OP='INSERT' THEN 'organization.created' ELSE 'organization.updated' END,'organization',new.id); RETURN new; END; $$;
REVOKE ALL ON FUNCTION public.audit_organization_changes() FROM PUBLIC;
CREATE TRIGGER weorex_organization_audit AFTER INSERT OR UPDATE ON public.organizations FOR EACH ROW EXECUTE FUNCTION public.audit_organization_changes();